import { useEffect,useMemo,useState } from 'react';
import { BookOpen,LayoutDashboard,CalendarDays,Users,NotebookPen,Target,TrendingUp,MessagesSquare,Lightbulb,Eye,FolderOpen,Images,ClipboardList,CheckCheck,ChartNoAxesCombined,Sparkles,Settings,Search,Bell,ChevronRight,ChevronLeft,Plus,ArrowUpRight,Clock,Check,FileText,Upload,Download,Sun,GraduationCap,ArrowRight,Filter,MoreHorizontal,MapPin,Link2,History,Save,LoaderCircle,ShieldCheck,AlertCircle,Calendar,Menu,X,LogOut,Paperclip,Send,RefreshCw,KeyRound,CheckCircle2 } from 'lucide-react';
