const manager=demo||['Tổ trưởng','Tổ phó'].includes(user.role);
const missing=members.flatMap(m=>categories.filter(c=>!docs.some(d=>d.assignee===m.id&&d.category===c)).map(c=>({member:m,category:c})));
async function refresh(){setError('');try{const res=await fetch('/api/workspace');if(res.status===401){setSigned(false);return;}const b=await res.json() as any;if(!res.ok)throw new Error(b.error);setSigned(true);setWorkspace(b.workspace);setUser(b.user);setYear(b.workspace.year);if(b.aiReady)setAiReady(true);if(b.records.length){setData(b.records);setDemo(false);}else{setData(demoRecords());setDemo(true);}}catch(e:any){setError(e.message);}finally{setLoading(false);}}
useEffect(()=>{const savedK=typeof window!=='undefined'?localStorage.getItem('tcm_gemini_api_key')||'':'';if(savedK){setGeminiKey(savedK);setAiReady(true);}const savedM=typeof window!=='undefined'?localStorage.getItem('tcm_gemini_model')||'gemini-3.8-flash':'gemini-3.8-flash';if(savedM)setGeminiModel(savedM);refresh();const hash=location.hash.slice(1);if(moduleNames[hash])setView(hash);const h=()=>{const v=location.hash.slice(1);if(moduleNames[v]){setView(v);setQuery('');}};window.addEventListener('hashchange',h);return()=>window.removeEventListener('hashchange',h);},[]);
async function testAiKey(keyToTest=geminiKey){if(!keyToTest?.trim())return toast.error('Vui lòng nhập API Key trước khi kiểm tra.');setKeyTesting(true);setKeyTestStatus(null);try{const res=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json','x-gemini-api-key':keyToTest.trim()},body:JSON.stringify({prompt:'Xin chào! Trợ lý chuyên môn đã sẵn sàng hoạt động chưa? Hãy trả lời ngắn gọn 1 câu.',year})});const b=await res.json() as any;if(!res.ok)throw new Error(b.error);setKeyTestStatus(`Kết nối thành công! Đã phản hồi từ ${b.modelUsed||geminiModel} (${b.durationMs}ms)`);toast.success('Khóa API Gemini hoạt động tốt!');}catch(err:any){setKeyTestStatus(`Lỗi kết nối: ${err.message}`);toast.error(err.message);}finally{setKeyTesting(false);}}
function saveAiKey(k:string,m=geminiModel){setGeminiKey(k);setGeminiModel(m);if(typeof window!=='undefined'){localStorage.setItem('tcm_gemini_api_key',k);localStorage.setItem('tcm_gemini_model',m);}if(k.trim())setAiReady(true);setAiModalOpen(false);toast.success('Đã lưu cấu hình Google Gemini API Key!');}
function nav(v:string,f='all'){setView(v);setFilter(f);setMemberFilter('');setQuery('');setTab('list');setNotifications(false);historySafe(v);window.scrollTo({top:0,behavior:'smooth'});}
function historySafe(v:string){window.history.replaceState(null,'','#'+v);}
async function mutation(body:any){setBusy(true);try{const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const b=await r.json() as any;if(!r.ok)throw new Error(b.error);await refresh();return b;}catch(e:any){toast.error(e.message);return null;}finally{setBusy(false);}}
function create(kind=view){setNote('');setEditor(blank(kind,year));}
async function save(){if(!editor?.title.trim())return toast.error('Vui lòng nhập tên.');const r=await mutation({action:'save',record:editor,note});if(r){setEditor(null);setSelected(null);toast.success('Đã lưu hồ sơ và phiên bản mới.');}}
async function detail(r:RecordItem){setSelected(r);setFiles([]);setHistory([]);setDetailLoading(true);try{const res=await fetch('/api/workspace?record='+r.id);const b=await res.json() as any;if(!res.ok)throw new Error(b.error);setHistory(b.versions||[]);setFiles(b.files||[]);}catch(e:any){toast.error(e.message);}finally{setDetailLoading(false);}}
async function status(r:RecordItem,s:string){if(s==='Yêu cầu chỉnh sửa'){setNote('');setEditor({...r,status:s});return;}if(await mutation({action:'save',record:{...r,status:s},note:'Chuyển trạng thái: '+s})){setSelected(null);toast.success('Đã cập nhật trạng thái.');}}
async function upload(file:File|undefined){if(!file||!selected)return;setBusy(true);try{const form=new FormData();form.append('file',file);form.append('record',selected.id);const res=await fetch('/api/files',{method:'POST',body:form});const b=await res.json() as any;if(!res.ok)throw new Error(b.error);await refresh();await detail({...selected,revision:selected.revision+1});toast.success('Đã lưu minh chứng.');}catch(e:any){toast.error(e.message);}finally{setBusy(false);}}
function exportData(kind:string,items=rows){const safe=(s:any)=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');if(kind==='pdf'){window.print();return;}let content,type,name;if(kind==='csv'){content='\uFEFF'+[['Loại','Tên','Người phụ trách','Trạng thái','Hạn','Nội dung'],...items.map(r=>[moduleNames[r.kind],r.title,ownerName(r.assignee),r.status,r.due,r.body])].map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');type='text/csv;charset=utf-8';name='Bao-cao-to-chuyen-mon.csv';}else{content=`<html><head><meta charset="utf-8"></head><body><h1>BÁO CÁO TỔ CHUYÊN MÔN</h1><p>${safe(workspace.name)} · ${safe(year)}${demo?' · DỮ LIỆU MẪU':''}</p><p>Hồ sơ hoàn thành: ${progress}% · Chờ duyệt: ${pending.length} · Công việc chưa hoàn thành: ${openTasks.length}</p>${items.map(r=>`<h2>${safe(r.title)}</h2><p>${safe(ownerName(r.assignee))} · ${safe(r.status)} · ${safe(r.due)}</p><p>${safe(r.body).replaceAll('\n','<br>')}</p>`).join('')}</body></html>`;type='application/msword;charset=utf-8';name='Bao-cao-to-chuyen-mon.doc';}const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast.success('Đã xuất báo cáo.');}
const filtered=rows.filter(r=>(query?`${r.title} ${r.body} ${r.category} ${ownerName(r.assignee)}`.toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi')):r.kind===view)&&(memberFilter?r.assignee===memberFilter:true)&&(filter==='all'||filter==='pending'&&['Chờ kiểm tra','Đã nộp'].includes(r.status)||filter==='late'&&!complete(r.status)&&r.due&&r.due<today||filter==='soon'&&!complete(r.status)&&r.due>=today&&r.due<=soonDate||filter===r.status));
